const DIVISION_DISTRICTS = {
  'HYDERABAD': ['SUJJAWAL', 'THATTA', 'DADU', 'TANDO ALLAHYAR', 'JAMSHORO', 'MATIARI', 'BADIN', 'HYDERABAD', 'TANDO MUHAMMAD KHAN'],
  'LARKANA': ['SHIKARPUR', 'KAMBAR', 'KASHMORE', 'JACOBABAD', 'LARKANA'],
  'MIRPURKHAS': ['THARPARKAR', 'MIRPURKHAS', 'UMERKOT'],
  'KARACHI': ['KARACHI MALIR', 'KARACHI KEAMARI', 'KARACHI WEST', 'KARACHI KORANGI', 'KARACHI CENTRAL', 'KARACHI EAST', 'KARACHI SOUTH'],
  'SHAHEED BENAZIR ABAD': ['NOSHERO FEROZ', 'SHAHEED BENAZIRABAD', 'SANGHAR'],
  'SUKKUR': ['KHAIRPUR', 'GHOTKI', 'SUKKUR'],
};

const HIGH_PRIORITY_DISEASES = [
  'Acute Flaccid Paralysis',
  'Acute Diarrhea Non Cholera',
  'Chickenpox/ Varicella',
  'CCHF',
  'Dengue Fever',
  'Diphtheria (Probable)',
  'HIV/AIDS',
  'Measles',
  'Mumps',
  'Neonatal Tetanus',
  'Pertussis',
  'Typhoid',
  'M-Pox',
];

function isHighPriority(diseaseName) {
  const name = (diseaseName || '').trim().toLowerCase();
  if (!name) return false;
  return HIGH_PRIORITY_DISEASES.some(hp => {
    const hpLower = hp.toLowerCase();
    return name.includes(hpLower) || hpLower.includes(name);
  });
}

const value = $input.first().json;
let records = value.records || (Array.isArray(value) ? value : []);

const parsed = $('Parse & Authorize Query6').first().json;
const restrictToDistrict = parsed.restrictToDistrict;
if (restrictToDistrict) {
  records = records.filter(r => (r.district || '').trim().toUpperCase() === restrictToDistrict);
}
const from = parsed.from;
const queryType = parsed.queryType;
const matchedDivision = parsed.matchedDivision;
const matchedDistrict = parsed.matchedDistrict;
const priorityFilter = parsed.priorityFilter;
const ambiguousDefaulted = parsed.ambiguousDefaulted;

const today = new Date().toLocaleDateString('en-PK', {
  timeZone: 'Asia/Karachi', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
});

let replyText;
let count = records.length;

function formatCaseBlock(r, i, includeLocation) {
  const diseaseName = r.disease_name || 'Unknown';
  const cases = r.cases ?? 'N/A';
  const focalPerson = r.focal_person || 'N/A';
  const locationText = [r.district, r.division].filter(Boolean).join(', ');
  const time = r.timestamp
    ? new Date(r.timestamp).toLocaleString('en-PK', { timeZone: 'Asia/Karachi', hour: '2-digit', minute: '2-digit', hour12: true })
    : 'N/A';
  const priorityTag = isHighPriority(diseaseName) ? '🔴 High Priority' : '🟡 Low Priority';
  const locationLine = includeLocation ? `📍 ${locationText}\n` : '';
  return `*${i + 1}. ${diseaseName}* — ${cases} case(s)\n${priorityTag}\n${locationLine}👤 Reported by: ${focalPerson}\n🕒 ${time}`;
}

if (queryType === 'priority_all') {
  const filtered = records.filter(r => {
    const high = isHighPriority(r.disease_name);
    return priorityFilter === 'high' ? high : !high;
  });

  const priorityLabel = priorityFilter === 'high' ? '🔴 High Priority' : '🟡 Low Priority';

  let grandTotal = 0;
  const sections = Object.entries(DIVISION_DISTRICTS).map(([division, districts]) => {
    const byDistrict = {};
    districts.forEach(d => { byDistrict[d] = 0; });

    filtered.forEach(r => {
      const district = (r.district || '').trim().toUpperCase();
      const recDivision = (r.division || '').trim().toUpperCase();
      if (recDivision === division && byDistrict.hasOwnProperty(district)) {
        byDistrict[district] += (Number(r.cases) || 0);
      }
    });

    const divisionTotal = Object.values(byDistrict).reduce((a, b) => a + b, 0);
    grandTotal += divisionTotal;

    const lines = Object.entries(byDistrict)
      .map(([district, cases]) => `   • ${district}: *${cases}*`)
      .join('\n');

    return `*${division}* (Total: ${divisionTotal})\n${lines}`;
  });

  replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 District-wise Breakdown (All Divisions)\n🏷️ Filter: ${priorityLabel}\n\n🔺 Grand Total: *${grandTotal}*\n\n${sections.join('\n\n')}`;
  count = grandTotal;

} else if (queryType === 'priority_location') {
  let scoped = records;
  let locationLabel = '';
  let showPerCaseLocation = false;

  if (matchedDistrict) {
    scoped = records.filter(r => (r.district || '').trim().toUpperCase() === matchedDistrict);
    locationLabel = `${matchedDistrict} District (${matchedDivision} Division)`;
    showPerCaseLocation = false;
  } else if (matchedDivision) {
    scoped = records.filter(r => (r.division || '').trim().toUpperCase() === matchedDivision);
    locationLabel = `${matchedDivision} Division`;
    showPerCaseLocation = true;
  }

  const filtered = scoped.filter(r => {
    const high = isHighPriority(r.disease_name);
    return priorityFilter === 'high' ? high : !high;
  });

  const priorityLabel = priorityFilter === 'high' ? '🔴 High Priority' : '🟡 Low Priority';
  const totalCases = filtered.reduce((sum, r) => sum + (Number(r.cases) || 0), 0);

  const clarifierNote = ambiguousDefaulted
    ? `\n\nℹ️ _Showing full ${matchedDivision} Division. To see only the ${matchedDivision} district, ask "${matchedDivision} district ${priorityFilter} priority disease".`
    : '';

  if (filtered.length === 0) {
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 ${locationLabel}\n🏷️ Filter: ${priorityLabel}\n\n✅ No ${priorityFilter} priority cases reported today.${clarifierNote}`;
  } else {
    const lines = filtered.map((r, i) => formatCaseBlock(r, i, showPerCaseLocation));
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 ${locationLabel}\n🏷️ Filter: ${priorityLabel}\n\n🔺 Total Cases: *${totalCases}*\n\n${lines.join('\n\n')}${clarifierNote}`;
  }
  count = totalCases;

} else if (queryType === 'district_wise_all') {
  let grandTotal = 0;
  const sections = Object.entries(DIVISION_DISTRICTS).map(([division, districts]) => {
    const byDistrict = {};
    districts.forEach(d => { byDistrict[d] = 0; });

    records.forEach(r => {
      const district = (r.district || '').trim().toUpperCase();
      const recDivision = (r.division || '').trim().toUpperCase();
      if (recDivision === division && byDistrict.hasOwnProperty(district)) {
        byDistrict[district] += (Number(r.cases) || 0);
      }
    });

    const divisionTotal = Object.values(byDistrict).reduce((a, b) => a + b, 0);
    grandTotal += divisionTotal;

    const lines = Object.entries(byDistrict)
      .map(([district, cases]) => `   • ${district}: *${cases}*`)
      .join('\n');

    return `*${division}* (Total: ${divisionTotal})\n${lines}`;
  });

  replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 District-wise Breakdown (All Divisions)\n\n🔺 Grand Total: *${grandTotal}*\n\n${sections.join('\n\n')}`;
  count = grandTotal;

} else if (queryType === 'division_wise_all') {
  const byDivision = {};
  Object.keys(DIVISION_DISTRICTS).forEach(d => { byDivision[d] = 0; });

  records.forEach(r => {
    const recDivision = (r.division || '').trim().toUpperCase();
    if (byDivision.hasOwnProperty(recDivision)) {
      byDivision[recDivision] += (Number(r.cases) || 0);
    }
  });

  const grandTotal = Object.values(byDivision).reduce((a, b) => a + b, 0);

  const lines = Object.entries(byDivision)
    .map(([division, cases]) => `• ${division}: *${cases}*`)
    .join('\n');

  replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 Division-wise Breakdown\n\n🔺 Grand Total: *${grandTotal}*\n\n${lines}`;
  count = grandTotal;

} else if (queryType === 'district_total') {
  const districtRecords = records.filter(r =>
    (r.district || '').trim().toUpperCase() === matchedDistrict
  );
  const totalCases = districtRecords.reduce((sum, r) => sum + (Number(r.cases) || 0), 0);

  if (districtRecords.length === 0) {
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 District: *${matchedDistrict}* (${matchedDivision} Division)\n\n✅ No cases reported today in this district.`;
  } else {
    const lines = districtRecords.map((r, i) => formatCaseBlock(r, i, false));
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 District: *${matchedDistrict}* (${matchedDivision} Division)\n\n🔺 Total Cases: *${totalCases}* (from ${districtRecords.length} report${districtRecords.length !== 1 ? 's' : ''})\n\n${lines.join('\n\n')}`;
  }
  count = totalCases;

} else if (queryType === 'division_total') {
  const divisionRecords = records.filter(r =>
    (r.division || '').trim().toUpperCase() === matchedDivision
  );
  const totalCases = divisionRecords.reduce((sum, r) => sum + (Number(r.cases) || 0), 0);

  const allDistricts = DIVISION_DISTRICTS[matchedDivision] || [];
  const byDistrict = {};
  allDistricts.forEach(d => { byDistrict[d] = 0; });
  divisionRecords.forEach(r => {
    const d = (r.district || 'Unknown').trim().toUpperCase();
    byDistrict[d] = (byDistrict[d] || 0) + (Number(r.cases) || 0);
  });

  const breakdown = Object.entries(byDistrict)
    .map(([district, cases]) => `• ${district}: *${cases}*`)
    .join('\n');

  const clarifierNote = ambiguousDefaulted
    ? `\n\nℹ️ _Showing full ${matchedDivision} Division total. To see only ${matchedDivision} district's figures, ask "${matchedDivision} district case report".`
    : '';

  replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n📍 Division: *${matchedDivision}*\n\n🔺 Total Cases: *${totalCases}*\n\n*District-wise breakdown:*\n${breakdown}${clarifierNote}`;
  count = totalCases;

} else if (queryType === 'disease_search') {
  const normalize = s => (s || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const term = normalize(parsed.diseaseSearchTerm);
  const matches = records.filter(r => {
    const name = normalize(r.disease_name);
    return name.includes(term) || term.includes(name);
  });
  const totalCases = matches.reduce((sum, r) => sum + (Number(r.cases) || 0), 0);

  if (matches.length === 0) {
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n🔍 Search: *${parsed.diseaseSearchTerm}*\n\n✅ No matching cases reported today. Check spelling or try a shorter disease name.`;
  } else {
    const lines = matches.map((r, i) => formatCaseBlock(r, i, true));
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n🔍 Search: *${parsed.diseaseSearchTerm}*\n\n🔺 Total Cases: *${totalCases}* (from ${matches.length} report${matches.length !== 1 ? 's' : ''})\n\n${lines.join('\n\n')}`;
  }
  count = totalCases;

} else if (queryType === 'top_diseases') {
  const topN = parsed.topN || 3;
  const byDisease = {};
  records.forEach(r => {
    const name = r.disease_name || 'Unknown';
    byDisease[name] = (byDisease[name] || 0) + (Number(r.cases) || 0);
  });
  const ranked = Object.entries(byDisease).sort((a, b) => b[1] - a[1]).slice(0, topN);

  if (ranked.length === 0) {
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n\n✅ No cases reported today.`;
  } else {
    const medals = ['🥇', '🥈', '🥉'];
    const lines = ranked.map(([name, cases], i) => {
      const icon = medals[i] || `${i + 1}.`;
      const tag = isHighPriority(name) ? '🔴' : '🟡';
      return `${icon} ${tag} *${name}* — ${cases} case(s)`;
    });
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n🏆 Top ${ranked.length} Diseases Today\n\n${lines.join('\n')}`;
  }
  count = ranked.reduce((sum, [, c]) => sum + c, 0);

} else if (queryType === 'list') {
  count = records.reduce((sum, r) => sum + (Number(r.cases) || 0), 0);
  if (records.length === 0) {
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n\n✅ No cases have been reported today.`;
  } else {
    const lines = records.map((r, i) => formatCaseBlock(r, i, true));
    replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n🔺 Total Cases: *${count}* (from ${records.length} report${records.length !== 1 ? 's' : ''})\n\n${lines.join('\n\n')}`;
  }

} else {
  count = records.reduce((sum, r) => sum + (Number(r.cases) || 0), 0);
  replyText = `📋 *Disease Surveillance Report*\n📅 ${today}\n\n🔺 Today's case reported is *${count}*.`;
}

return [{
  json: {
    from,
    count,
    queryType,
    matchedDivision,
    matchedDistrict,
    replyText
  }
}];

const AUTHORIZED_USERS = {
  '92xyz': { role: 'PDSRU', district: null },
  '92xyz': { role: 'DDSRU', district: 'KARACHI WEST' },
  '92xyz': { role: 'DDSRU', district: 'THARPARKAR' },
  '92xyz': { role: 'PDSRU', district: null },
  // ... add all your numbers here
};                                          

const DIVISION_DISTRICTS = {
  'HYDERABAD': ['SUJJAWAL', 'THATTA', 'DADU', 'TANDO ALLAHYAR', 'JAMSHORO', 'MATIARI', 'BADIN', 'HYDERABAD', 'TANDO MUHAMMAD KHAN'],
  'LARKANA': ['SHIKARPUR', 'KAMBAR', 'KASHMORE', 'JACOBABAD', 'LARKANA'],
  'MIRPURKHAS': ['THARPARKAR', 'MIRPURKHAS', 'UMERKOT'],
  'KARACHI': ['KARACHI MALIR', 'KARACHI KEAMARI', 'KARACHI WEST', 'KARACHI KORANGI', 'KARACHI CENTRAL', 'KARACHI EAST', 'KARACHI SOUTH'],
  'SHAHEED BENAZIR ABAD': ['NOSHERO FEROZ', 'SHAHEED BENAZIRABAD', 'SANGHAR'],
  'SUKKUR': ['KHAIRPUR', 'GHOTKI', 'SUKKUR'],
};

const AMBIGUOUS_NAMES = ['HYDERABAD', 'LARKANA', 'MIRPURKHAS', 'SHAHEED BENAZIR ABAD', 'SUKKUR'];

const DISTRICT_TO_DIVISION = {};
for (const [division, districts] of Object.entries(DIVISION_DISTRICTS)) {
  districts.forEach(d => { DISTRICT_TO_DIVISION[d] = division; });
}

const LOCATIONS = [];
for (const [division, districts] of Object.entries(DIVISION_DISTRICTS)) {
  LOCATIONS.push({ name: division, type: 'division', division: null, ambiguousDefaulted: false });
  districts.forEach(d => {
    if (!AMBIGUOUS_NAMES.includes(d)) {
      LOCATIONS.push({ name: d, type: 'district', division, ambiguousDefaulted: false });
    }
  });
}
LOCATIONS.sort((a, b) => b.name.length - a.name.length);

const item = $input.first().json;
const value = item.entry ? item.entry[0]?.changes?.[0]?.value : item;
const message = value?.messages?.[0];

if (!message) {
  return [{
    json: {
      from: '', senderName: '', messageText: '',
      isAuthorized: false, isQuery: false, queryType: null,
      matchedDivision: null, matchedDistrict: null, priorityFilter: null,
      diseaseSearchTerm: null, topN: null, role: null, userDistrict: null,
      restrictToDistrict: null, accessDeniedMessage: null,
      ambiguousDefaulted: false, action: 'ignore'
    }
  }];
}

const from = (message?.from || '').trim();
const senderName = value?.contacts?.[0]?.profile?.name || '';

const user = AUTHORIZED_USERS[from] || null;
const isAuthorized = user !== null;
const role = user?.role || null;
const userDistrict = user?.district || null;
const userDivision = userDistrict ? (DISTRICT_TO_DIVISION[userDistrict] || null) : null;

const listReplyId = message?.interactive?.list_reply?.id || null;
const messageText = (message?.text?.body || '').trim();
const upperText = messageText.toUpperCase();

const MENU_ID_MAP = {
  'MENU_TODAY_COUNT':   { queryType: 'count',              priorityFilter: null   },
  'MENU_TODAY_LIST':    { queryType: 'list',                priorityFilter: null   },
  'MENU_DIVISION_WISE': { queryType: 'division_wise_all',   priorityFilter: null   },
  'MENU_DISTRICT_WISE': { queryType: 'district_wise_all',   priorityFilter: null   },
  'MENU_HIGH_PRIORITY': { queryType: 'priority_all',        priorityFilter: 'high' },
  'MENU_LOW_PRIORITY':  { queryType: 'priority_all',        priorityFilter: 'low'  },
  'MENU_NON_REPORTING': { queryType: 'non_reporting_districts', priorityFilter: null },
};

let queryType = null;
let matchedDivision = null;
let matchedDistrict = null;
let priorityFilter = null;
let diseaseSearchTerm = null;
let topN = null;
let ambiguousDefaulted = false;
let willSendMenu = false;

if (isAuthorized && listReplyId && MENU_ID_MAP[listReplyId]) {
  queryType = MENU_ID_MAP[listReplyId].queryType;
  priorityFilter = MENU_ID_MAP[listReplyId].priorityFilter;

} else if (isAuthorized && messageText !== '') {
  const menuTriggers = ['MENU', 'HI', 'HELLO', 'START', 'HELP'];

  if (menuTriggers.includes(upperText)) {
    willSendMenu = true;

  } else if (userDistrict && /\bMY DISTRICT\b/.test(upperText)) {
    // Quick shortcut for DDSRU users: "my district case report" -> their own district
    queryType = 'district_total';
    matchedDistrict = userDistrict;
    matchedDivision = userDivision;

  } else {
    const NON_REPORTING_TRIGGERS = ['NOT REPORTED', "HAVEN'T REPORTED", 'HAVENT REPORTED',
      "HASN'T REPORTED", 'HASNT REPORTED', 'NON REPORTING', 'NON-REPORTING',
      'NOT SUBMITTED', 'PENDING REPORT', 'MISSING REPORT', "DIDN'T REPORT",
      'DIDNT REPORT', 'NOT YET REPORTED'];
    const isNonReportingQuery = NON_REPORTING_TRIGGERS.some(t => upperText.includes(t)) ||
      (upperText.includes('PENDING') && upperText.includes('DISTRICT'));

    const mentionsDivisionWord = upperText.includes('DIVISION');
    const mentionsDistrictWord = upperText.includes('DISTRICT');
    const isDistrictWiseQuery = upperText.includes('DISTRICT WISE') || upperText.includes('DISTRICTWISE');
    const isDivisionWiseQuery = upperText.includes('DIVISION WISE') || upperText.includes('DIVISIONWISE');

    const hasHighWord = /\bHIGH\b/.test(upperText);
    const hasLowWord = /\bLOW\b/.test(upperText);
    if (hasHighWord) priorityFilter = 'high';
    else if (hasLowWord) priorityFilter = 'low';

    let matchedLocation = null;
    if (!isNonReportingQuery && !isDistrictWiseQuery && !isDivisionWiseQuery) {
      for (const name of AMBIGUOUS_NAMES) {
        if (upperText.includes(name)) {
          if (mentionsDistrictWord) {
            matchedLocation = { name, type: 'district', division: name, ambiguousDefaulted: false };
          } else if (mentionsDivisionWord) {
            matchedLocation = { name, type: 'division', division: null, ambiguousDefaulted: false };
          } else {
            matchedLocation = { name, type: 'division', division: null, ambiguousDefaulted: true };
          }
          break;
        }
      }
      if (!matchedLocation) {
        for (const loc of LOCATIONS) {
          if (upperText.includes(loc.name)) {
            matchedLocation = { name: loc.name, type: loc.type, division: loc.division, ambiguousDefaulted: loc.ambiguousDefaulted };
            break;
          }
        }
      }
    }

    const askingWords = ['TOTAL', 'CASE', 'REPORT', 'HOW MANY', 'DETAIL', 'DISEASE', 'PRIORITY'];
    const mentionsAsking = askingWords.some(w => upperText.includes(w));
    const isLocationQuery = matchedLocation !== null && mentionsAsking;

    const topMatch = upperText.match(/\bTOP\s*(\d+)?\b/);
    const isTopQuery = topMatch !== null && (upperText.includes('DISEASE') || upperText.includes('CASE'));

    const listKeywords = ['all case', 'all cases', 'list', 'detail', 'details', 'give me all', 'full list', 'show all'];
    const isListQuery = listKeywords.some(k => messageText.toLowerCase().includes(k));

    const countKeywords = ['how many', 'disease', 'case', 'report', 'today'];

    if (isNonReportingQuery) {
      queryType = 'non_reporting_districts';
    } else if (isDistrictWiseQuery) {
      queryType = 'district_wise_all';
    } else if (isLocationQuery && priorityFilter) {
      queryType = 'priority_location';
      ambiguousDefaulted = matchedLocation.ambiguousDefaulted || false;
      if (matchedLocation.type === 'division') { matchedDivision = matchedLocation.name; }
      else { matchedDistrict = matchedLocation.name; matchedDivision = matchedLocation.division; }
    } else if (isDivisionWiseQuery) {
      queryType = 'division_wise_all';
    } else if (isLocationQuery) {
      ambiguousDefaulted = matchedLocation.ambiguousDefaulted || false;
      if (matchedLocation.type === 'division') {
        queryType = 'division_total';
        matchedDivision = matchedLocation.name;
      } else {
        queryType = 'district_total';
        matchedDistrict = matchedLocation.name;
        matchedDivision = matchedLocation.division;
      }
    } else if (priorityFilter && (upperText.includes('DISEASE') || upperText.includes('CASE') || upperText.includes('REPORT'))) {
      queryType = 'priority_all';
    } else if (isTopQuery) {
      queryType = 'top_diseases';
      topN = topMatch[1] ? parseInt(topMatch[1], 10) : 3;
    } else {
      const STOPWORDS = ['TOTAL', 'CASE', 'CASES', 'REPORT', 'REPORTED', 'REPORTING', 'HOW', 'MANY', 'TODAY',
        'DISEASE', 'DISEASES', 'IN', 'OF', 'THE', 'IS', 'ARE', 'WHAT', 'TELL', 'ME', 'GIVE', 'SHOW',
        'PLEASE', 'ALL', 'DISTRICT', 'DIVISION', 'WISE', 'HIGH', 'LOW', 'PRIORITY',
        'LIST', 'DETAIL', 'DETAILS', 'FULL', 'MY'];
      const words = upperText.replace(/[^A-Z0-9\s]/g, '').split(/\s+/).filter(Boolean);
      const leftover = words.filter(w => !STOPWORDS.includes(w));
      const candidate = leftover.join(' ').trim();

      const mentionsCountKeyword = countKeywords.some(k => messageText.toLowerCase().includes(k));

      if (candidate.length >= 3 && mentionsCountKeyword) {
        queryType = 'disease_search';
        diseaseSearchTerm = candidate;
      } else if (isListQuery) {
        queryType = 'list';
      } else if (mentionsCountKeyword) {
        queryType = 'count';
      }
    }
  }
}

// ================== UNIFIED ACTION + PERMISSION DECISION ==================
let action;
let restrictToDistrict = null;
let accessDeniedMessage = null;

if (messageText === '' && !listReplyId) {
  action = 'ignore';

} else if (!isAuthorized) {
  action = 'unauthorized';

} else if (willSendMenu) {
  action = 'send_menu';

} else if (queryType === null) {
  action = 'ignore';

} else if (role === 'DDSRU') {
  const PROVINCE_WIDE = ['district_wise_all', 'division_wise_all', 'non_reporting_districts'];

  if (PROVINCE_WIDE.includes(queryType)) {
    action = 'access_denied';
    accessDeniedMessage = `🚫 *Access Restricted*\n\nThis report covers all districts and is only available to PDSRU.\nAs a DDSRU user, you can only view *${userDistrict}* district.\n\nTry: "my district case report"`;

  } else if (queryType === 'division_total') {
    action = 'access_denied';
    accessDeniedMessage = `🚫 *Access Restricted*\n\nDivision-level reports include other districts and are only available to PDSRU.\nYou can only view *${userDistrict}* district.\n\nTry: "my district case report"`;

  } else if (queryType === 'district_total' && matchedDistrict !== userDistrict) {
    action = 'access_denied';
    accessDeniedMessage = `🚫 *Access Restricted*\n\nYou are only authorized to view *${userDistrict}* district.\nYou asked about *${matchedDistrict}*, which is outside your access.`;

  } else if (queryType === 'priority_location' && matchedDistrict && matchedDistrict !== userDistrict) {
    action = 'access_denied';
    accessDeniedMessage = `🚫 *Access Restricted*\n\nYou are only authorized to view *${userDistrict}* district.\nYou asked about *${matchedDistrict}*, which is outside your access.`;

  } else if (queryType === 'priority_location' && !matchedDistrict && matchedDivision) {
    action = 'access_denied';
    accessDeniedMessage = `🚫 *Access Restricted*\n\nDivision-level reports include other districts and are only available to PDSRU.\nYou can only view *${userDistrict}* district.\n\nTry: "high priority disease in ${userDistrict}"`;

  } else {
    action = 'query';
    restrictToDistrict = userDistrict;
    // Convert province-wide priority queries into a district-scoped view
    // for DDSRU, so the reply is a clean per-case list, not an empty-looking
    // 6-division breakdown.
    if (queryType === 'priority_all') {
      queryType = 'priority_location';
      matchedDistrict = userDistrict;
      matchedDivision = userDivision;
    }
  }

} else {
  // PDSRU -- full access, no restriction
  action = 'query';
}

const isQuery = action === 'query';

return [{
  json: {
    from, senderName, messageText, isAuthorized, isQuery, queryType,
    matchedDivision, matchedDistrict, priorityFilter, diseaseSearchTerm, topN,
    role, userDistrict, restrictToDistrict, accessDeniedMessage,
    ambiguousDefaulted, action
  }
}];

const parsed = $('Parse & Authorize Query6').first().json;
const from = parsed.from;
const role = parsed.role;
const userDistrict = parsed.userDistrict;

let rows;

if (role === 'PDSRU') {
  rows = [
    { id: 'MENU_TODAY_COUNT',   title: 'Total Cases Today',   description: "Get today's total case count" },
    { id: 'MENU_TODAY_LIST',    title: 'Full Case List',      description: 'See every case reported today' },
    { id: 'MENU_DIVISION_WISE', title: 'Division-wise',       description: 'Totals for every division' },
    { id: 'MENU_DISTRICT_WISE', title: 'District-wise',       description: 'Totals for every district' },
    { id: 'MENU_HIGH_PRIORITY', title: 'High Priority',       description: 'High priority diseases today' },
    { id: 'MENU_LOW_PRIORITY',  title: 'Low Priority',        description: 'Low priority diseases today' },
  ];
} else {
  // DDSRU -- scoped to their own district only, no province-wide options
  rows = [
    { id: 'MENU_TODAY_COUNT',   title: 'My District Total',     description: `Today's case count for ${userDistrict}` },
    { id: 'MENU_TODAY_LIST',    title: 'My District Case List', description: `Every case reported in ${userDistrict}` },
    { id: 'MENU_HIGH_PRIORITY', title: 'High Priority',         description: `High priority diseases in ${userDistrict}` },
    { id: 'MENU_LOW_PRIORITY',  title: 'Low Priority',          description: `Low priority diseases in ${userDistrict}` },
  ];
}

const payload = {
  messaging_product: 'whatsapp',
  to: from,
  type: 'interactive',
  interactive: {
    type: 'list',
    header: { type: 'text', text: 'Disease Surveillance Bot' },
    body: { text: "Please select what you'd like to check:" },
    footer: { text: role === 'PDSRU' ? 'PDSRU' : `DDSRU - ${userDistrict}` },
    action: {
      button: 'View Options',
      sections: [{ title: 'Reports', rows }]
    }
  }
};

return [{ json: { payload } }];

// ⚠️ Keep this in sync with "Parse & Authorize Query" and "Build Daily Summary & Recipients"
const AUTHORIZED_USERS = {
  '92xyz': { role: 'PDSRU', district: null, password: 'xyz' },
  '92xyz': { role: 'DDSRU', district: 'THARPARKAR', password: 'xyz' },
  '92xyz': { role: 'DDSRU', district: 'KARACHI WEST', password: 'xyz' },
  // ... add all your 32-33 numbers here, each with their own password
};

const SESSION_TIMEOUT_MS = 10 * 60 * 1000; // 10 minutes

const item = $input.first().json;
const value = item.entry ? item.entry[0]?.changes?.[0]?.value : item;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { ...item, loginAction: 'ignore' } }];
}

const from = (message?.from || '').trim();
const messageText = (message?.text?.body || '').trim();
const user = AUTHORIZED_USERS[from] || null;

if (!user) {
  // Not an authorized number at all -- let the normal flow handle "unauthorized" messaging
  return [{ json: { ...item, loginAction: 'not_authorized_number' } }];
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};

const now = Date.now();
const session = staticData.sessions[from];
const isLoggedIn = session && (now - session.lastActivity) < SESSION_TIMEOUT_MS;

if (isLoggedIn) {
  // Extend the session (sliding timeout) and let this message flow through normally
  staticData.sessions[from].lastActivity = now;
  return [{ json: { ...item, loginAction: 'proceed' } }];
}

// Not logged in (first message, or session expired) -- treat this message as a password attempt
if (messageText === user.password) {
  staticData.sessions[from] = { lastActivity: now };
  return [{ json: { ...item, loginAction: 'login_success', from, role: user.role } }];
} else {
  return [{ json: { ...item, loginAction: 'login_failed', from } }];
}

const { loginAction, from, role } = $input.first().json;

let textMessage;
if (loginAction === 'login_success') {
  textMessage = `✅ *Login Successful*\n\nWelcome to the Disease Surveillance Bot${role ? ` (${role})` : ''}.\nType "menu" to see your options, or ask a question directly.`;
} else {
  textMessage = `🔒 *Login Required*\n\nPlease enter your password to continue.`;
}

// Returns clear, un-nested string variables to the next node
return [{ 
  json: { 
    from: from,
    text: textMessage 
  } 
}];
